class Solution:
    def maxFreqSum(self, s: str) -> int:
        vowel = set(['a', 'e', 'i', 'o', 'u'])
        count = defaultdict(int)
        max_v = 0
        max_c = 0
        for c in s:
            count[c] += 1
            if c in vowel:
                max_v = max(max_v, count[c])
            else:
                max_c = max(max_c, count[c])

        return max_c + max_v
